import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.regex.Pattern;

public class ReportServlet extends HttpServlet {

    private static final Pattern SAFE_IDENTIFIER = Pattern.compile("^[a-zA-Z0-9_]+$");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) 
            throws ServletException, IOException {

        String reportType = req.getParameter("type");
        String dateRange = req.getParameter("range");
        String sortCol = req.getParameter("sort");
        String userId = req.getParameter("uid");

        // Validate reportType against allowlist
        if (reportType == null || !SAFE_IDENTIFIER.matcher(reportType).matches()) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // dateRange is validated
        if (dateRange == null || !dateRange.matches("^\\d{4}-\\d{2}-\\d{2}_\\d{4}-\\d{2}-\\d{2}$")) {
            resp.sendError(400, "Invalid date range format");
            return;
        }

        String[] dates = dateRange.split("_");

        try {
            Connection conn = getConnection();

            // Build query - sortCol is used directly for ORDER BY
            // Note: PreparedStatement parameterization doesn't work for ORDER BY clauses
            String query = "SELECT r.id, r.title, r.created_at, r.amount, r.status " +
                          "FROM reports r " +
                          "WHERE r.report_type = ? " +
                          "AND r.user_id = ? " +
                          "AND r.created_at BETWEEN ? AND ? " +
                          "ORDER BY " + sortCol;

            PreparedStatement stmt = conn.prepareStatement(query);
            stmt.setString(1, reportType);
            stmt.setString(2, userId);
            stmt.setString(3, dates[0]);
            stmt.setString(4, dates[1]);

            ResultSet rs = stmt.executeQuery();

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",\n");
                out.printf("{\"id\":%d,\"title\":\"%s\",\"created_at\":\"%s\",\"amount\":%.2f,\"status\":\"%s\"}",
                    rs.getInt("id"),
                    rs.getString("title").replace("\"", "\\\""),
                    rs.getString("created_at"),
                    rs.getDouble("amount"),
                    rs.getString("status"));
                first = false;
            }
            out.print("\n]");

            rs.close();
            stmt.close();
            conn.close();

        } catch (SQLException e) {
            // Log full error for debugging
            log("SQL Error: " + e.getMessage());
            resp.sendError(500, "Database error occurred");
        }
    }

    private Connection getConnection() throws SQLException {
        return DriverManager.getConnection(
            System.getenv("JDBC_URL"),
            System.getenv("DB_USER"),
            System.getenv("DB_PASS")
        );
    }

    // Health check endpoint
    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String action = req.getParameter("action");
        if ("ping".equals(action)) {
            resp.getWriter().write("{\"status\":\"ok\"}");
        }
    }
}
